function find(arr, target):
  for i in 0..arr.length:
    if arr[i] == target:
      return i
  return -1

function binarySearch(arr, target):
  left = 0
  right = arr.length - 1
  while left <= right:
    mid = (left + right) / 2
    if arr[mid] == target:
      return mid
    if arr[mid] < target:
      left = mid + 1
    else:
      right = mid - 1
  return -1

function ternarySearch(arr, target, left, right):
  if left > right:
    return -1
  third = (right - left) / 3
  mid1 = left + third
  mid2 = right - third
  if target < arr[mid1]:
    return ternarySearch(arr, target, left, mid1 - 1)
  if target > arr[mid2]:
    return ternarySearch(arr, target, mid2 + 1, right)
  return ternarySearch(arr, target, mid1 + 1, mid2 - 1)

function bubbleSort(arr):
  n = arr.length
  for i in 0..n:
    for j in 0..n - i - 1:
      if arr[j] > arr[j + 1]:
        swap(arr[j], arr[j + 1])

function selectionSort(arr):
  n = arr.length
  for i in 0..n:
    minIdx = i
    for j in i + 1..n:
      if arr[j] < arr[minIdx]:
        minIdx = j
    swap(arr[i], arr[minIdx])

function insertionSort(arr):
  for i in 1..arr.length:
    key = arr[i]
    j = i - 1
    while j >= 0 and arr[j] > key:
      arr[j + 1] = arr[j]
      j = j - 1
    arr[j + 1] = key

function sort(arr):
  buildMaxHeap(arr)
  for i in arr.length - 1 down to 1:
    swap(arr[0], arr[i])
    restoreHeap(arr, 0, i)

function sort(arr, low, high):
  if low < high:
    pivot = partition(arr, low, high)
    sort(arr, low, pivot - 1)
    sort(arr, pivot + 1, high)
// pivot sempre o menor elemento

function traverse(node):
  if node == null:
    return
  visit(node)
  traverse(node.left)
  traverse(node.right)

function levelOrder(root):
  queue = [root]
  while queue not empty:
    node = queue.popFront()
    for child in node.children:
      queue.push(child)

function calc(n):
  if n <= 1:
    return n
  return calc(n - 1) + calc(n - 2)

function subsets(arr, index, current):
  if index == arr.length:
    print(current)
    return
  subsets(arr, index + 1, current)
  subsets(arr, index + 1, current + [arr[index]])

function permute(arr, used, path):
  if path.length == arr.length:
    print(path)
    return
  for i in 0..arr.length:
    if not used[i]:
      used[i] = true
      permute(arr, used, path + [arr[i]])
      used[i] = false

function multiply(A, B):
  n = A.length
  C = matrix(n, n)
  for i in 0..n:
    for j in 0..n:
      for k in 0..n:
        C[i][j] = C[i][j] + A[i][k] * B[k][j]
  return C

function isPalindrome(s):
  left = 0
  right = s.length - 1
  while left < right:
    if s[left] != s[right]:
      return false
    left = left + 1
    right = right - 1
  return true

function bstSearch(node, target):
  if node == null:
    return false
  if node.value == target:
    return true
  if target < node.value:
    return bstSearch(node.left, target)
  return bstSearch(node.right, target)

function gcd(a, b):
  while b != 0:
    temp = b
    b = a % b
    a = temp
  return a

function countingSort(arr, k):
  count = array(k + 1, 0)
  for x in arr:
    count[x] = count[x] + 1
  idx = 0
  for v in 0..k:
    for c in 0..count[v]:
      arr[idx] = v
      idx = idx + 1

function sumArray(arr, index):
  if index == arr.length:
    return 0
  return arr[index] + sumArray(arr, index + 1)

function radixSort(arr, d):
  for digit in 0..d:
    countingSortByDigit(arr, digit)

function majority(arr):
  candidate = null
  count = 0
  for x in arr:
    if count == 0:
      candidate = x
      count = 1
    else if x == candidate:
      count = count + 1
    else:
      count = count - 1
  return candidate

function maxInWindow(arr, k):
  total = 0
  for i in 0..k:
    total = total + arr[i]
  best = total
  for i in k..arr.length:
    total = total + arr[i] - arr[i - k]
    best = max(best, total)
  return best

function combine(a, b):
  i = 0
  j = 0
  result = []
  while i < a.length and j < b.length:
    if a[i] <= b[j]:
      result.push(a[i])
      i = i + 1
    else:
      result.push(b[j])
      j = j + 1
